import{_ as a,o as i,c as r,ak as n,bw as o,bx as l,by as u,bz as t}from"./chunks/framework.BnR3M3Bd.js";const g=JSON.parse('{"title":"Ajustement de la caméra du joueur avec Cinemachine","description":"","frontmatter":{},"headers":[],"relativePath":"18_SuiviJoueurCamera_Cinemachine.md","filePath":"18_SuiviJoueurCamera_Cinemachine.md","lastUpdated":1769182706000}'),s={name:"18_SuiviJoueurCamera_Cinemachine.md"};function c(m,e,d,p,h,v){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="ajustement-de-la-camera-du-joueur-avec-cinemachine" tabindex="-1">Ajustement de la caméra du joueur avec Cinemachine <a class="header-anchor" href="#ajustement-de-la-camera-du-joueur-avec-cinemachine" aria-label="Permalink to “Ajustement de la caméra du joueur avec Cinemachine”">​</a></h1><p>La manière la plus simple de suivre un joueur avec une caméra est de parenter la caméra au joueur. Cependant, cela peut sembler rigide et peu naturel. Une meilleure approche consiste programmer les comportements de la caméra pour qu&#39;elle suive le joueur de manière fluide et dynamique, s&#39;arrête aux limites du jeu et permette au joueur de se déplacer dans une zone sans que la caméra ne le suive pas immédiatement.</p><p>Heureusement, Unity propose un outil appelé Cinemachine qui facilite grandement cette tâche.</p><h2 id="qu-est-ce-que-cinemachine" tabindex="-1">Qu&#39;est-ce que Cinemachine ? <a class="header-anchor" href="#qu-est-ce-que-cinemachine" aria-label="Permalink to “Qu&#39;est-ce que Cinemachine ?”">​</a></h2><p>Cinemachine est un puissant outil de gestion de caméra dans Unity autant en 2d qu&#39;en 3d qui permet de créer des comportements de caméra dynamiques et fluides. C&#39;est simple à mettre en place et offre une grande flexibilité pour suivre le joueur dans un jeu.</p><h2 id="etapes-pour-configurer-cinemachine-pour-suivre-le-joueur" tabindex="-1">Étapes pour configurer Cinemachine pour suivre le joueur <a class="header-anchor" href="#etapes-pour-configurer-cinemachine-pour-suivre-le-joueur" aria-label="Permalink to “Étapes pour configurer Cinemachine pour suivre le joueur”">​</a></h2><ol><li><p><strong>Installer Cinemachine</strong> :</p><ul><li>Ouvrez Unity et allez dans le menu <code>Window</code> &gt; <code>Package Manager</code>.</li><li>Recherchez <code>Cinemachine</code> dans la liste des packages disponibles.</li><li>Cliquez sur <code>Install</code> pour ajouter Cinemachine à votre projet.</li></ul></li></ol><p><img src="'+o+'" alt="Installer Cinemachine"></p><ol start="2"><li><p><strong>Ajouter une Virtual Camera</strong> :</p><ul><li>Dans la hiérarchie, faites un clic droit et sélectionnez <code>Cinemachine</code> &gt; <code>Cinemachine Camera</code>.</li><li>Une nouvelle caméra virtuelle sera ajoutée à votre scène.</li></ul></li></ol><p><img src="'+l+'" alt="Ajouter une Camera Cinemachine"></p><ol start="3"><li><p><strong>Configurer la Virtual Camera</strong> :</p><ul><li>Sélectionnez la caméra virtuelle dans la hiérarchie.</li><li>Dans l&#39;inspecteur, trouvez le composant <code>CinemachineCamera</code>.</li><li>Dans le champ <code>Lens</code>, vous pouvez ajuster les paramètres de la caméra selon vos besoins.</li><li>Dans le champ <code>Tracking Target</code>, faites glisser et déposez l&#39;objet joueur ( ou le GameObject que vous souhaitez suivre).</li><li>Dans le champ <code>Position Control</code>, choisissez <code>follow</code> pour que la caméra suive le joueur.</li></ul></li><li><p><strong>Ajuster les paramètres de la caméra</strong> :</p><ul><li>Après avoir choisi <code>follow</code>, vous pouvez ajuster les paramètres de suivi tels que la <code>Damping</code> pour rendre le mouvement de la caméra plus fluide. Cela créé un delai entre le mouvement du joueur et celui de la caméra.</li><li>Vous pouvez également ajuster le décalage de la caméra pour qu&#39;elle ne soit pas centrée exactement sur le joueur, mais légèrement en avant ou en hauteur selon vos préférences. <strong>Laissez -10 sur l&#39;axe Z pour une vue 2D classique.</strong></li></ul></li><li><p><strong>Limiter le mouvement de la caméra dans une zone</strong> :</p></li></ol><ul><li>Dans le champ <code>Add Extension</code>, vous pouvez ajouter des extensions comme <code>Cinemachine Confiner 2D</code> pour que la caméra reste dans des limites définies du niveau. (voir plus bas)</li><li>Ajouter un objet vide dans la scène et nommez-le <code>LimitesCamera</code>.</li><li>Ajoutez un composant <code>Box Collider 2D</code> ou <code>Polygon Collider 2D</code> selon la forme de votre niveau.</li><li>Cochez la case <code>Is Trigger</code> pour que le collider ne bloque pas les objets.(important!!)</li><li>Ajustez la taille et la position du collider pour qu&#39;il englobe toute la zone</li><li>Dans la caméra virtuelle, ajoutez l&#39;extension <code>Cinemachine Confiner 2D</code>.</li><li>Faites glisser l&#39;objet <code>LimitesCamera</code> dans le champ <code>Bounding Shape 2D</code> de l&#39;extension.</li></ul><p><img src="'+u+'" alt="Configuration de Cinemachine"></p><p><img src="'+t+'" alt="Limites de la caméra"></p><p><a href="https://docs.unity3d.com/Packages/com.unity.cinemachine@3.1/manual/Cinemachine2D.html" target="_blank" rel="noreferrer">Documentation Unity sur Cinemachine</a></p>',15)])])}const j=a(s,[["render",c]]);export{g as __pageData,j as default};
